#!/usr/bin/env python3
"""A small, dependency-free CSV filtering and aggregation command-line tool."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import OrderedDict
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path
from typing import Iterable


class InputError(Exception):
    """An error caused by command input or CSV contents."""


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Filter and aggregate an RFC-4180 CSV file.")
    parser.add_argument("input", metavar="INPUT.csv", help="CSV file to read")
    parser.add_argument("--where", action="append", default=[], metavar="COLUMN=VALUE",
                        help="Keep rows whose column exactly matches VALUE (repeatable)")
    parser.add_argument("--group-by", metavar="COLUMN", help="Column used for aggregation")
    parser.add_argument("--sum", dest="sum_columns", action="append", default=[], metavar="COLUMN",
                        help="Numeric column to sum (repeatable)")
    parser.add_argument("--avg", dest="avg_columns", action="append", default=[], metavar="COLUMN",
                        help="Numeric column to average (repeatable)")
    parser.add_argument("--output", choices=("json", "csv"), default="json",
                        help="Output format (default: json)")
    args = parser.parse_args(argv)
    if (args.sum_columns or args.avg_columns) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    return args


def read_csv(path: str) -> tuple[list[str], list[tuple[int, dict[str, str]]]]:
    """Return headers and logical records, retaining one-based CSV row numbers."""
    try:
        with Path(path).open("r", encoding="utf-8", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise InputError("input CSV has no header row") from None

            if not headers:
                raise InputError("input CSV has no header row")
            if any(header == "" for header in headers):
                raise InputError("CSV headers must be non-empty")
            duplicates = sorted({header for header in headers if headers.count(header) > 1})
            if duplicates:
                raise InputError("CSV headers must be unique: " + ", ".join(duplicates))

            records: list[tuple[int, dict[str, str]]] = []
            row_number = 1
            for fields in reader:
                row_number += 1
                if len(fields) != len(headers):
                    raise InputError(
                        f"row {row_number} has {len(fields)} fields; expected {len(headers)}"
                    )
                records.append((row_number, dict(zip(headers, fields))))
            return headers, records
    except FileNotFoundError:
        raise InputError(f"input file not found: {path}") from None
    except PermissionError:
        raise InputError(f"cannot read input file: {path}") from None
    except UnicodeDecodeError as exc:
        raise InputError(f"input is not valid UTF-8: {exc}") from None
    except csv.Error as exc:
        raise InputError(f"malformed CSV: {exc}") from None
    except OSError as exc:
        raise InputError(f"cannot read input file: {exc}") from None


def require_columns(headers: list[str], columns: Iterable[str]) -> None:
    known = set(headers)
    for column in columns:
        if column not in known:
            raise InputError(f"unknown column: {column}")


def parse_filters(raw_filters: list[str], headers: list[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for raw in raw_filters:
        if "=" not in raw:
            raise InputError(f"malformed filter {raw!r}; expected COLUMN=VALUE")
        column, value = raw.split("=", 1)
        if not column:
            raise InputError(f"malformed filter {raw!r}; column must not be empty")
        require_columns(headers, [column])
        filters.append((column, value))
    return filters


def parse_decimal(value: str, row_number: int, column: str) -> Decimal:
    if value == "":
        raise InputError(f"invalid numeric value at row {row_number}, column {column!r}: blank value")
    try:
        number = Decimal(value)
    except InvalidOperation:
        raise InputError(
            f"invalid numeric value at row {row_number}, column {column!r}: {value!r}"
        ) from None
    if not number.is_finite():
        raise InputError(
            f"invalid numeric value at row {row_number}, column {column!r}: {value!r}"
        )
    return number


def decimal_text(value: Decimal) -> str:
    """Format a Decimal without exponent notation or unnecessary zeroes."""
    if value.is_zero():
        return "0"
    text = format(value.normalize(), "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def aggregate(
    rows: list[tuple[int, dict[str, str]]], group_by: str,
    sum_columns: list[str], avg_columns: list[str],
) -> tuple[list[str], list[OrderedDict[str, str | Decimal]]]:
    numeric_columns = list(dict.fromkeys(sum_columns + avg_columns))
    # Enough precision for the exact sums of all supplied decimal significands,
    # including a carry from addition.  Division follows Decimal's documented
    # finite working precision for averages that are repeating decimals.
    max_digits = 1
    for row_number, row in rows:
        for column in numeric_columns:
            max_digits = max(max_digits, len(parse_decimal(row[column], row_number, column).as_tuple().digits))
    precision = max(28, max_digits + len(str(max(1, len(rows)))) + 2)

    grouped: dict[str, dict[str, object]] = {}
    with localcontext() as context:
        context.prec = precision
        for row_number, row in rows:
            group = row[group_by]
            state = grouped.setdefault(group, {"count": 0, "totals": {column: Decimal(0) for column in numeric_columns}})
            state["count"] = int(state["count"]) + 1
            totals = state["totals"]
            assert isinstance(totals, dict)
            for column in numeric_columns:
                totals[column] += parse_decimal(row[column], row_number, column)

        columns = [group_by] + [f"sum_{column}" for column in sum_columns] + [f"avg_{column}" for column in avg_columns]
        result: list[OrderedDict[str, str | Decimal]] = []
        for group in sorted(grouped):
            state = grouped[group]
            totals = state["totals"]
            count = int(state["count"])
            assert isinstance(totals, dict)
            record: OrderedDict[str, str | Decimal] = OrderedDict([(group_by, group)])
            for column in sum_columns:
                record[f"sum_{column}"] = totals[column]
            for column in avg_columns:
                record[f"avg_{column}"] = totals[column] / count
            result.append(record)
    return columns, result


def json_value(value: str | Decimal) -> str:
    return decimal_text(value) if isinstance(value, Decimal) else json.dumps(value, ensure_ascii=False)


def write_json(records: list[dict[str, str | Decimal]]) -> None:
    # json.dumps intentionally handles strings/escaping; Decimal tokens are
    # inserted as JSON numbers so their exact decimal spelling is retained.
    objects = []
    for record in records:
        members = [json.dumps(key, ensure_ascii=False) + ":" + json_value(value)
                   for key, value in record.items()]
        objects.append("{" + ",".join(members) + "}")
    sys.stdout.write("[" + ",".join(objects) + "]\n")


def write_csv(columns: list[str], records: list[dict[str, str | Decimal]]) -> None:
    writer = csv.writer(sys.stdout, lineterminator="\n")
    writer.writerow(columns)
    for record in records:
        writer.writerow([decimal_text(record[column]) if isinstance(record[column], Decimal) else record[column]
                         for column in columns])


def run(args: argparse.Namespace) -> None:
    headers, rows = read_csv(args.input)
    filters = parse_filters(args.where, headers)
    require_columns(headers, [column for column in (args.group_by, *args.sum_columns, *args.avg_columns) if column is not None])
    filtered = [(number, row) for number, row in rows if all(row[column] == value for column, value in filters)]

    if args.sum_columns or args.avg_columns:
        columns, records = aggregate(filtered, args.group_by, args.sum_columns, args.avg_columns)
    else:
        columns = headers
        records = [row for _, row in filtered]

    if args.output == "json":
        write_json(records)
    else:
        write_csv(columns, records)


def main(argv: list[str] | None = None) -> int:
    try:
        run(parse_args(argv))
    except InputError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
